import type { Carrier } from '../types.ts';
import { HttpError } from './http.ts';

const S10_WEIGHTS = [8, 6, 4, 2, 3, 5, 9, 7];

/** UPU S10 check digit for 8 serial digits (algorithm: docs/carriers.md). */
export function s10CheckDigit(serial: string): number {
  const sum = [...serial].reduce((acc, digit, i) => acc + Number(digit) * S10_WEIGHTS[i], 0);
  const result = 11 - (sum % 11);
  if (result === 10) return 0;
  if (result === 11) return 5;
  return result;
}

/** ATP: 2 letters, 8 digits, 1 check digit, `AT`. Expects an already upper-cased value. */
const ATP_FORMAT = /^[A-Z]{2}(\d{8})(\d)AT$/;

/**
 * Carrier-specific tracking number check. Only ATP is validated strictly; all other carriers
 * accept any non-empty value on purpose (their formats change too often, and strict checks
 * once rejected valid DHL numbers for two days).
 *
 * The error `message` is shown verbatim to the warehouse staff, hence German.
 */
export function assertValidTrackingNumber(carrier: Carrier, trackingNumber: string): void {
  if (carrier !== 'ATP') return;

  const match = ATP_FORMAT.exec(trackingNumber);
  if (!match) {
    throw new HttpError(
      400,
      'INVALID_TRACKING_NUMBER',
      `Ungültige Sendungsnummer "${trackingNumber}" für Österreichische Post (ATP): ` +
        'erwartet werden 2 Buchstaben, 8 Ziffern, 1 Prüfziffer und "AT" (z. B. RR123456785AT).',
    );
  }
  if (s10CheckDigit(match[1]) !== Number(match[2])) {
    throw new HttpError(
      400,
      'INVALID_TRACKING_NUMBER',
      `Ungültige Sendungsnummer "${trackingNumber}" für Österreichische Post (ATP): ` +
        'die Prüfziffer stimmt nicht. Bitte die Nummer auf dem Etikett prüfen.',
    );
  }
}
